function createIcon(name: keyof typeof iconData): IconComponent {
  const { viewBox, body } = iconData[name];
  function SolarIcon({ size = 24, strokeWidth, ...props }: IconProps) {
    const html = strokeWidth == null ? body : body.replace(/stroke-width="[^"]*"/g, `stroke-width="${strokeWidth}"`);
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox={viewBox}
        width={size}
        height={size}
        focusable="false"
        aria-hidden={props["aria-label"] ? undefined : true}
        {...props}
        dangerouslySetInnerHTML={{ __html: html }}
      />
    );
  }
  SolarIcon.displayName = name;
  return SolarIcon;
}

